class NumArray:
    def __init__(self, nums: list[int]):
        self.n = len(nums)
        self.nums = nums[:]                # current values, needed to turn an update into a delta
        self.bit = [0] * (self.n + 1)      # Fenwick tree, 1-indexed; bit[i] covers (i - lowbit(i), i]
        for i, v in enumerate(nums):
            self._add(i + 1, v)            # n adds of O(log n) each

    def _add(self, i: int, delta: int) -> None:
        while i <= self.n:
            self.bit[i] += delta
            i += i & -i                    # jump to the next node whose block contains i

    def _prefix(self, i: int) -> int:
        total = 0
        while i > 0:
            total += self.bit[i]
            i -= i & -i                    # strip the lowest set bit: at most log n steps
        return total

    def update(self, index: int, val: int) -> None:
        self._add(index + 1, val - self.nums[index])   # blocks store sums, so add the change
        self.nums[index] = val

    def sumRange(self, left: int, right: int) -> int:
        return self._prefix(right + 1) - self._prefix(left)

