def query(self, left, right, idx, qLeft, qRight):
    # out of range
    if qRight < left or qLeft > right:
        return 0

    if qLeft <= left and right <= qRight:
        return self.tree[idx]

    mid = (left + right) // 2
    resLeft = self.query(left, mid, 2*idx + 1, qLeft, qRight)
    resRight = self.query(mid + 1, right, 2*idx + 2, qLeft, qRight)
    return resLeft + resRight
